 internal void Set(int percent,Color background,bool round){if(configured&&lastPercent==percent&&fill==background&&rounded==round){Sync();return;}bool recolour=fill!=background;configured=true;lastPercent=percent;fill=background;rounded=round;bool next=percent<100;bool changed=enabled!=next||recolour;enabled=next;if(changed){Restore();if(enabled){target.TransparencyKey=key;MakeClear(target);}else{target.TransparencyKey=Color.Empty;Plate.Hide();}}if(enabled){Plate.BackColor=fill;Plate.Opacity=Math.Max(.3,percent/100.0);}Sync();}
 void Restore(){foreach(var pair in originals)if(!pair.Key.IsDisposed){SolidText.Stop(pair.Key);var task=pair.Key as ThemeTasks;if(task!=null)task.SolidGlyphs=false;var edit=pair.Key as SpellTextBox;if(edit!=null)edit.SolidGlyphs=false;var read=pair.Key as FormattedPage;if(read!=null)read.SolidGlyphs=false;if(pair.Key.BackColor==key)pair.Key.BackColor=pair.Value;}originals.Clear();}

 void MakeClear(Control control){if(!(control is Label||control is ToolStrip||control is Button||control is ComboBox||(control is ListBox&&!(control is ThemeTasks)))){originals[control]=control.BackColor;control.BackColor=key;var task=control as ThemeTasks;if(task!=null)task.SolidGlyphs=true;var edit=control as SpellTextBox;if(edit!=null)edit.SolidGlyphs=true;var read=control as FormattedPage;if(read!=null)read.SolidGlyphs=true;}foreach(Control child in control.Controls)MakeClear(child);}
 internal void Sync(){if(syncing||Plate.IsDisposed)return;syncing=true;try{if(!enabled||!target.Visible||target.WindowState==FormWindowState.Minimized){Plate.Hide();return;}Rectangle next=target.Bounds;bool moved=Plate.Bounds!=next;if(Plate.TopMost!=target.TopMost)Plate.TopMost=target.TopMost;if(plateSize!=target.Size||plateRounded!=rounded){plateSize=target.Size;plateRounded=rounded;var old=Plate.Region;Plate.Region=rounded&&target.Region!=null?target.Region.Clone():null;if(old!=null)old.Dispose();}if(!Plate.Visible){Plate.Bounds=next;Plate.Show();}if(moved)SetWindowPos(Plate.Handle,target.Handle,next.X,next.Y,next.Width,next.Height,0x210);}finally{syncing=false;}}
 Control At(Point screen){Control child=target;while(true){var next=child.GetChildAtPoint(child.PointToClient(screen),GetChildAtPointSkip.Invisible);if(next==null)break;child=next;}return child;}
 internal void ForwardWheel(Point screen,int delta){Control child=At(screen);int flags=((Control.ModifierKeys&Keys.Shift)!=0?4:0)|((Control.ModifierKeys&Keys.Control)!=0?8:0);SendMessage(child.Handle,0x20A,new IntPtr((delta<<16)|flags),new IntPtr((screen.Y<<16)|(screen.X&65535)));}
 internal void Forward(Point screen,int message){int hit=BorderlessWindow.Hit(target,screen);var memo=target as MemoWindow;var main=target as Companion;bool locked=memo!=null?memo.Pref.Locked:main!=null&&(main.store.Pref.Locked||main.IsTabbed);if(message==0x201&&hit>1&&!locked&&target.FormBorderStyle==FormBorderStyle.None&&target.WindowState!=FormWindowState.Maximized){Native.ReleaseCapture();SendMessage(target.Handle,0xA1,new IntPtr(hit),new IntPtr((screen.Y<<16)|(screen.X&65535)));return;}Control child=At(screen);target.Activate();Native.SetForegroundWindow(target.Handle);target.ActiveControl=child;child.Select();child.Focus();Point p=child.PointToClient(screen);int flags=((Control.ModifierKeys&Keys.Shift)!=0?4:0)|((Control.ModifierKeys&Keys.Control)!=0?8:0)|(message==0x201?1:0);SendMessage(child.Handle,message,new IntPtr(flags),new IntPtr((p.Y<<16)|(p.X&65535)));}
 public void Dispose(){Restore();if(!Plate.IsDisposed)Plate.Close();originals.Clear();}
 [DllImport("user32.dll")]static extern bool SetWindowPos(IntPtr window,IntPtr after,int x,int y,int w,int h,int flags);
