}
sealed class BackgroundPlate:Form {
 internal BackgroundPlate(){DoubleBuffered=true;SetStyle(ControlStyles.AllPaintingInWmPaint|ControlStyles.OptimizedDoubleBuffer,true);}
 internal Action<Point,int> Forward,Wheel;protected override bool ShowWithoutActivation{get{return true;}}protected override CreateParams CreateParams{get{var p=base.CreateParams;p.ExStyle|=0x08000080;return p;}}
 protected override void OnMouseWheel(MouseEventArgs e){if(Wheel!=null)Wheel(PointToScreen(e.Location),e.Delta);}
 protected override void OnMouseDown(MouseEventArgs e){if(Forward!=null)Forward(PointToScreen(e.Location),e.Button==MouseButtons.Right?0x204:0x201);}
 protected override void OnMouseUp(MouseEventArgs e){if(Forward!=null)Forward(PointToScreen(e.Location),e.Button==MouseButtons.Right?0x205:0x202);}
}
